class WebappSeoCommunitySupportTests(unittest.TestCase):
 def test_manifest_exact_roles_callable(self):
  self.assertEqual([x["id"] for x in FEATURES],[f"future-{n}" for n in range(2222,2282)]);self.assertEqual(len({x["api"] for x in FEATURES}),60)
  allowed={"self","member","analyst","campaign_manager","seo_editor","seo_admin","community_moderator","community_admin","support_agent","support_admin","security_reviewer"}
  for x in FEATURES:self.assertIn(x["role"],allowed);self.assertTrue(callable(getattr(o,x["api"])))
 def test_no_io_dynamic_execution_or_html_sink(self):
  s=inspect.getsource(o)
  for x in ("requests.","urllib.request","subprocess","eval(","exec(","innerHTML","os.system"):self.assertNotIn(x,s)
 def test_unknown_events_rejected(self):
  for domain,fn in (("seo",o.webapp_seo_external_event),("community",o.community_external_event)):
   v=signed("unknown",domain);self.assertFalse(fn(v["event"],v["key"])["valid"])
 def test_webhook_type_and_domain_are_signed(self):
  v=signed("crawl.completed","seo");v["event"]["type"]="metadata.changed";self.assertFalse(o.webapp_seo_external_event(v["event"],v["key"])["valid"])
  v=signed("community.updated","seo");self.assertFalse(o.community_external_event(v["event"],v["key"])["valid"])
 def test_destructive_actions_are_plans(self):self.assertFalse(o.webapp_seo_digital_twin({},[{"action":"set_title","value":"T"}])["persisted"]);self.assertFalse(o.community_batch_plan(["x"],"tag")["executed"])
